import sys, json

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(arr):
    if not arr: return None
    nodes = [TreeNode(v) if v is not None else None for v in arr]
    it = iter(nodes)
    try:
        root = next(it)
    except StopIteration:
        return None
    queue = [root]
    for node in queue:
        if node:
            try:
                node.left = next(it)
                queue.append(node.left)
                node.right = next(it)
                queue.append(node.right)
            except StopIteration:
                break
    return root

def solve(root, targetSum):
    res = []
    def dfs(node, curr_sum, path):
        if not node: return
        curr_sum += node.val
        if not node.left and not node.right:
            if curr_sum == targetSum:
                res.append(path + [node.val])
            return
        dfs(node.left, curr_sum, path + [node.val])
        dfs(node.right, curr_sum, path + [node.val])
    dfs(root, 0, [])
    return res

if __name__ == '__main__':
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) >= 2:
        try:
            arr = json.loads(lines[0])
            targetSum = int(lines[1])
            root = build_tree(arr)
            print(json.dumps(solve(root, targetSum)))
        except:
            print("[]")
    else:
        print("[]")

